<template>
  <article class="answer-canvas" aria-label="数据答案画布">
    <header class="answer-cover"><div class="answer-kicker"><span class="answer-dot"></span> DATA ANSWER <span class="answer-edition">数据简报</span></div><h2>{{ question || displayTitle || title }}</h2><div class="answer-meta"><span>{{ sources.length }} 个结果集</span><span>{{ failed ? '尚未取得查询结果' : `本次返回 ${returnedRows} 行` }}</span><span>单位依字段定义</span></div></header>
    <div v-if="summary" class="answer-summary"><span>{{ failed?'查询未完成':current.analysis_status==='model_unavailable'?'数据快照 · AI 解读未完成':current.analysis_status==='deterministic'?'历史查询事实':current.analysis_status==='model_generated'?'AI 结论速览':'结论速览' }}</span><p>{{ summary }}</p></div>
    <p v-if="current.analysis_status==='model_unavailable'" class="analysis-warning">AI 问数未完整完成，当前内容不能视为 AI 分析结论。若已有查询数据，可在图表与明细中核对后重试。</p>
    <div v-if="sources.length > 1" class="source-tabs" aria-label="选择结果集"><button v-for="(source,index) in sources" :key="index" :aria-pressed="activeSource === index" @click="activeSource=index">{{ source.dataset_name || `结果 ${index+1}` }}</button></div>
    <div v-if="scalarMetrics.length" class="answer-metrics"><div v-for="key in scalarMetrics" :key="key"><span>{{ key }}</span><strong>{{ formatFact(current.rows[0][key]) }}</strong></div></div>
    <div class="answer-toolbar"><nav aria-label="答案视图"><button v-for="[key,label] in [['visual','图表'],['data','数据'],['insight','解读']]" :key="key" :aria-pressed="tab===key" @click="tab=key">{{ label }}</button></nav><div class="answer-actions"><button v-if="allowDownload && current.rows?.length" @click="downloadData">导出数据 ↓</button><button v-if="allowDownload" @click="downloadReport">下载简报 ↗</button></div></div>
    <section v-if="tab==='visual'" class="answer-visual">
      <div v-if="metrics.length && hasChart" class="chart-controls"><span>{{ current.dataset_name || '查询结果' }}</span><label v-if="metrics.length>1 && !configuredChart">指标 <select v-model="metric"><option v-for="key in metrics" :key="key">{{ key }}</option></select></label><label v-if="!configuredChart">图形 <select v-model="chartType"><option value="auto">自动</option><option value="bar">条形图</option><option value="line">折线图</option></select></label></div>
      <EvidenceChart v-if="hasChart" :dataset="current" :renderer="renderChart" :allow-auto="allowAutoChart" :metric-key="metric" :chart-type="chartType" :selected-indices="selectedIndices" @select-row="toggleRow" />
      <p v-if="hasChart && !configuredChart" class="chart-interaction-hint">点选图形聚焦数据 · 再选一项并排比较</p>
      <div v-else class="canvas-empty"><span class="empty-glyph">▤</span><h3>{{ current.rows?.length ? '这份结果更适合查看明细' : failed ? '查询未完成，请重试' : '当前范围没有返回记录' }}</h3><p>{{ current.rows?.length ? '保留完整字段与原始数值，不强行生成图表。' : failed ? '模型生成或查询校验未完成，尚不能判断该范围有无数据。' : '查询已执行，检查时间、筛选条件与当前账号的数据范围。' }}</p><button v-if="!failed" @click="tab='data'">查看数据</button></div>
    </section>
    <section v-else-if="tab==='data'" class="answer-table"><div class="table-scroller"><table><thead><tr><th v-if="current.rows?.length" scope="col">聚焦</th><th v-for="column in columns" :key="column" scope="col"><button @click="sort(column)">{{ column }} <span v-if="sortKey===column">{{ descending?'↓':'↑' }}</span></button></th></tr></thead><tbody><tr v-for="(row,index) in pageRows" :key="index"><td><button class="row-focus-button" :aria-pressed="selectedIndices.includes(current.rows.indexOf(row))" :aria-label="`聚焦第${current.rows.indexOf(row)+1}行：${row[dimension] ?? '记录'}`" @click="toggleRow(current.rows.indexOf(row))">{{ selectedIndices.includes(current.rows.indexOf(row))?'已选':'＋' }}</button></td><td v-for="column in columns" :key="column" :class="{numeric:typeof row[column]==='number'}">{{ formatFact(row[column]) }}</td></tr></tbody></table></div><div class="table-pagination"><span>共 {{ current.rows?.length || 0 }} 行已返回数据 · 每页 20 行</span><div><button :disabled="page===0" @click="page--">上一页</button><span>{{ page+1 }} / {{ pageCount }}</span><button :disabled="page+1>=pageCount" @click="page++">下一页</button></div></div></section>
    <section v-else class="answer-insight"><span class="insight-label">结果解读</span><p v-if="!insight">暂无独立解读，请以返回的数据为准。</p><div v-else class="insight-prose">{{ insight }}</div></section>
    <section v-if="selectedIndices.length" class="focus-lens" aria-label="数据聚焦与对照" aria-live="polite">
      <header><div><span class="lens-kicker">FOCUS LENS / 本次结果</span><h3>{{ selectedIndices.length===2?'把差异放在一起看':'聚焦一个数据对象' }}</h3></div><button @click="selectedIndices=[]">清除选择 ×</button></header>
      <p class="lens-note">{{ selectedIndices.length===2?'右侧减去左侧，逐字段对照；不汇总、不推断原因。':'从下方选择另一条记录，或返回图表点选。' }}</p>
      <div class="lens-picks"><label>加入对照<select aria-label="选择对照记录" :value="''" @change="toggleRow(Number($event.target.value)); $event.target.value='' "><option value="" disabled>选择本次返回的记录…</option><option v-for="(row,index) in current.rows" :key="index" :value="index" :disabled="selectedIndices.includes(index)">{{ index+1 }} · {{ row[dimension] ?? '记录' }}</option></select></label><span>最多两项 · 第三项替换右侧</span></div>
      <div class="lens-table-scroll"><table><thead><tr><th>字段</th><th v-for="index in selectedIndices" :key="index">{{ current.rows[index]?.[dimension] ?? `第 ${index+1} 行` }}</th><th v-if="selectedIndices.length===2">差值（右 − 左）</th></tr></thead><tbody><tr v-for="column in columns" :key="column"><th>{{ column }}</th><td v-for="index in selectedIndices" :key="index">{{ formatFact(current.rows[index]?.[column]) }}</td><td v-if="selectedIndices.length===2" class="lens-difference">{{ difference(column) }}</td></tr></tbody></table></div>
      <div v-if="allowFollowUp" class="lens-next"><span>沿着这个关注点继续</span><button @click="draftFollowUp">{{ selectedIndices.length===2?'把这两个对象带入追问 ↗':'围绕这个对象继续提问 ↗' }}</button><small>仅填入草稿，确认后再查询</small></div>
    </section>
    <footer class="answer-provenance"><details><summary>口径与来源 <span>{{ current.dataset_name || '本次结果' }} ↗</span></summary><div class="provenance-content"><p>数据集：{{ current.dataset_name || '未返回名称' }}<template v-if="current.dataset_id"> · #{{ current.dataset_id }}</template></p><p>展示本次返回的查询快照；数值、单位及筛选条件以字段与实际查询为准。</p><p v-if="review">审核记录：{{ review }}</p><details v-if="allowTechnical && current.sql"><summary>查看实际 SQL</summary><pre>{{ current.sql }}</pre></details></div></details><div v-if="showDetailsButton" class="report-entry-actions"><button @click="$emit('view-report')">HTML 分析报告 ↗</button><button @click="$emit('viewDetails')">分析过程 ↗</button></div></footer>
  </article>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import EvidenceChart from './EvidenceChart.vue'
import { numericColumns,dimensionColumn,formatFact,datasetCsv,answerHtml,queryFailed } from '../../utils/answerPresentation'
const props=defineProps({title:String,question:String,displayTitle:String,report:String,dataset:Object,datasets:{type:Array,default:()=>[]},route:Object,flowLabel:String,flowClass:String,flowHint:String,showDetailsButton:Boolean,allowDownload:Boolean,allowTechnical:Boolean,allowAutoChart:Boolean,renderChart:Function,allowFollowUp:Boolean})
const emit=defineEmits(['viewDetails','view-report','follow-up'])
const selectedIndices=ref([])
const sources=computed(()=>props.datasets.length?props.datasets:props.dataset?[props.dataset]:[])
const activeSource=ref(0),tab=ref('visual'),metric=ref(''),chartType=ref('auto'),page=ref(0),sortKey=ref(''),descending=ref(false)
const current=computed(()=>sources.value[activeSource.value] || {})
const failed=computed(()=>queryFailed(current.value))
const columns=computed(()=>current.value.columns || Object.keys(current.value.rows?.[0] || {}))
const dimension=computed(()=>dimensionColumn(current.value,metric.value))
const metrics=computed(()=>numericColumns(current.value))
const configuredChart=computed(()=>current.value.report_spec?.charts?.length)
const hasChart=computed(()=>configuredChart.value || (props.allowAutoChart && metrics.value.length && dimensionColumn(current.value,metric.value) && current.value.rows?.length>1))
const scalarMetrics=computed(()=>current.value.rows?.length===1?metrics.value.slice(0,6):[])
const returnedRows=computed(()=>sources.value.reduce((n,ds)=>n+(ds.rows?.length || 0),0))
const insight=computed(()=>failed.value?'本次查询未完成，尚不能判断业务数据是否为空。请重新提问；如果持续失败，请检查模型服务连接。':current.value.analysis || props.report || '')
const summary=computed(()=>{
  const line=String(insight.value).split('\n').map(s=>s.trim()).find(s=>s && !/^(#|\||[-•] |核心结论$|查询事实$|结论$)/.test(s)) || ''
  const plain=line.replace(/\*\*|`/g,'')
  return plain.length>240?plain.slice(0,240)+'…':plain
})
const review=computed(()=>current.value.agent3_review?.review_summary || '')
const sortedRows=computed(()=>{const rows=[...(current.value.rows || [])];if(!sortKey.value)return rows;return rows.sort((a,b)=>{const x=a[sortKey.value],y=b[sortKey.value];const order=x==null?1:y==null?-1:typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'zh-CN');return descending.value?-order:order})})
const pageCount=computed(()=>Math.max(1,Math.ceil(sortedRows.value.length/20)))
const pageRows=computed(()=>sortedRows.value.slice(page.value*20,(page.value+1)*20))
function sort(key){descending.value=sortKey.value===key?!descending.value:false;sortKey.value=key;page.value=0}
watch(current,()=>{selectedIndices.value=[];metric.value=metrics.value[0] || '';page.value=0;sortKey.value=''}, {immediate:true})
function toggleRow(index){
  if(!Number.isInteger(index) || index<0 || index>=(current.value.rows?.length || 0))return
  const selected=selectedIndices.value
  selectedIndices.value=selected.includes(index)?selected.filter(i=>i!==index):selected.length<2?[...selected,index]:[selected[0],index]
}
function difference(column){
  if(!metrics.value.includes(column))return '—'
  const a=current.value.rows?.[selectedIndices.value[0]]?.[column],b=current.value.rows?.[selectedIndices.value[1]]?.[column]
  return typeof a==='number' && typeof b==='number' && Number.isFinite(a) && Number.isFinite(b)?formatFact(b-a):'—'
}
function draftFollowUp(){
  if(!props.allowFollowUp)return
  const labels=selectedIndices.value.map(index=>`${dimension.value || '记录'}=${formatFact(current.value.rows[index]?.[dimension.value])}（返回第${index+1}行）`)
  emit('follow-up',{dataset_id:current.value.dataset_id,dataset_name:current.value.dataset_name,question_text:`基于上一问「${props.question || props.title || ''}」的时间范围和指标口径，${labels.length===2?'对比':'进一步查看'}${labels.join(' 与 ')}。请先核对筛选对象与口径。`})
}
function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const safeName=text=>String(text || '问数结果').replace(/[\\/:*?"<>|\r\n]/g,'_').slice(0,70)
const downloadData=()=>download(datasetCsv(current.value),'text/csv;charset=utf-8',safeName(current.value.dataset_name)+'.csv')
const downloadReport=()=>download(answerHtml(props.question || props.title,sources.value,props.report),'text/html;charset=utf-8',safeName(props.question || props.title)+'.html')
</script>
