id-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:24px;padding:4px 32px 26px}.answer-metrics div{display:flex;flex-direction:column;gap:10px}.answer-metrics span{font-size:12px;color:#66716b}.answer-metrics strong{font-size:32px;font-weight:500;letter-spacing:-1px;font-variant-numeric:tabular-nums}.canvas-empty{text-align:center;padding:30px 12px;color:#66716b}.empty-glyph{font-size:30px;color:#66716b}.canvas-empty h3{font-size:15px;font-weight:500;color:#59647c}.canvas-empty p{font-size:12px}.canvas-empty button{background:#f0f4ef;color:#386553;padding:8px 15px;border-radius:6px}.table-scroller{overflow:auto;max-height:520px}.answer-table table{border-collapse:collapse;width:100%;font-size:12px}.answer-table th,.answer-table td{padding:13px 22px;text-align:left;border-bottom:1px solid #eef0f6;white-space:nowrap}.answer-table th{position:sticky;top:0;background:#f0f4ef;color:#66716b;font-weight:500}.answer-table tbody tr:hover{background:#f0f4ef}.answer-table td.numeric{text-align:right;font-variant-numeric:tabular-nums}.table-pagination{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;padding:16px 24px;font-size:12px;color:#66716b}.table-pagination>div{display:flex;gap:12px;align-items:center}.answer-insight{padding:26px 32px;font-size:13px;line-height:1.9;color:#48534d}.insight-label{font-size:12px;color:#386553}.insight-prose{white-space:pre-wrap;overflow-wrap:anywhere;margin-top:12px}.answer-provenance{display:flex;align-items:baseline;justify-content:space-between;gap:16px;padding:16px 32px;border-top:1px solid #eef0f5;font-size:12px;color:#66716b}.answer-provenance>details{flex:1;min-width:0}.answer-provenance summary{cursor:pointer;list-style:none}.answer-provenance summary span{margin-left:15px;color:#66716b}.provenance-content{margin-top:16px;line-height:1.9;overflow-wrap:anywhere}.provenance-content pre{white-space:pre-wrap;font-size:12px;background:#f0f4ef;padding:12px}@media(max-width:600px){.answer-cover{padding:20px}.answer-cover h2{font-size:19px}.answer-edition{display:none}.answer-toolbar{padding:0 20px}.answer-toolbar nav{gap:18px}.answer-actions{gap:10px}.answer-visual{padding:16px}.answer-provenance{padding:16px 20px;flex-direction:column}.answer-insight{padding:20px}.answer-metrics{padding:0 20px 20px}.chart-controls select{max-width:160px}}

