header>button{white-space:nowrap}.lens-picks label{flex-wrap:wrap;max-width:100%}.lens-picks select{max-width:100%}.lens-next{gap:10px}.lens-next button,.lens-picks select{min-height:44px}}@media(prefers-reduced-motion:reduce){.focus-lens{animation:none}}
